INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(1200, 0, 12, 0, 0, 0, 'Elwynn Forest', 'Elwynn Forest is the green heartland of the kingdom of Stormwind, a country of tall hardwoods, rushing rivers, quiet lakes and farmland made rich by frequent rain. Stormwind City stands in its northwestern hills, and from its gates the road runs south to Goldshire, the largest of the forest towns. The land remembers war. In the First War the orcish Horde marched through these woods, overran Goldshire and destroyed Northshire Abbey before reducing the capital to ruins, and only after the Second War did the people return to rebuild. Today the danger is quieter but it is everywhere. With much of the Stormwind Army fighting in distant lands, a thin line of marshals, deputies and guards must hold the forest against kobolds swarming its mines, Riverpaw gnolls on the western border, murlocs creeping up the eastern streams and the red-masked thieves of the Defias Brotherhood, who are quietly draining gold from Elwynn''s mines. The marshals now deputize any volunteer willing to help.', 'warcraft.wiki.gg/wiki/Elwynn_Forest (terrain, First War, Goldshire falls, Northshire Abbey destroyed, resettling after the Second War); npc_text 2286 (Deputy Rainer: bulk of the army abroad); npc_text 50016 (Deputy Willem); quest 783 description and reward text; quest 54 reward text (Acting Deputy status); page_text 79 (Defias gold collection from the Elwynn mines)'),
(1201, 1, 12, 1, 0, 0, 'Northshire Valley', 'Northshire Valley lies behind a wall and border gates northeast of Goldshire, a sheltered vale of farms and vineyards gathered around Northshire Abbey. The Knights of the Silver Hand had made it fairly safe, but that peace is fraying. A clan of kobolds has infested the woods north of the abbey, and sick young wolves, which the hunter Eagan Peltskinner believes were driven here out of Duskwood, prowl the slopes while livestock goes missing. Worse, a gang of thieves in red bandanas has appeared across the river to the east, calling itself a brotherhood. Marshal McBride and his deputies enlist every willing hand they can find.', 'warcraft.wiki.gg/wiki/Elwynn_Forest (Northshire east of Stormwind behind a wall, Goldshire southwest of Northshire); quest 54 description (past the border gates); quest 3100 reward text (Silver Hand made this place fairly safe); quest 7 description; quest 33 description; quest 18 description; page_text 209-211 (McBride''s reports: kobolds, thieves, wolves from Duskwood, missing livestock)'),
(1202, 1, 12, 2, 0, 0, 'Northshire Abbey', 'Northshire Abbey was founded by clerics of the Holy Light who came south from Lordaeron, and it has long served the people and soldiers of Stormwind. Orcs destroyed it in the First War, though refugees carried its sacred tomes out of the ruins, and in the Second War Cho''gall''s Twilight''s Hammer clan made it their headquarters. Afterward Archbishop Alonsus Faol helped rebuild it and gathered clerics, priests and paladins into the Brotherhood of Northshire. Today the abbey trains new defenders of the realm: warriors and paladins drill within its halls, mages and priests study in its library wing, and Brother Neals keeps the stores of food and wine from the bell tower.', 'warcraft.wiki.gg/wiki/Northshire_Abbey (founding, First War, Twilight''s Hammer headquarters, Faol and the Brotherhood of Northshire, recruitment and training center); page_text 2291 (Faol helped reform the Brotherhood of Northshire); page_text 2439, 2445, 2463, 2465 (trainers in the abbey and its library wing); quest 3905 description (Brother Neals manages food and drink, in the bell tower)'),
(1203, 1, 12, 3, 0, 0, 'Echo Ridge Mine', 'North of the abbey the hills rise to Echo Ridge, where Northshire''s own mine cuts into the rock. Kobolds have claimed it. They first camped in the woods nearby, and Marshal McBride''s scouts soon found the infestation larger than anyone had guessed, with kobold workers and laborers digging through the tunnels, candles perched on their heads. The marshal warns that every day the vermin are left in peace, they gain a firmer foothold in the valley. Clearing the mine is among the first duties he gives the volunteers who answer Northshire''s call.', 'quest 15 description; quest 21 description and reward text; page_text 209 (kobolds north of the abbey and in Echo Ridge Mine); page_text 15 (candles the kobolds wear on their heads); DB spawns: Kobold Worker 257 and Kobold Laborer 80 around -8700,-150'),
(1204, 1, 12, 4, 0, 0, 'Northshire Vineyards', 'East of the abbey, across the river, lie the Northshire Vineyards, whose grapes were once the pride of Stormwind. Milly Osworth was in the middle of her harvest when the Defias Brotherhood moved in, and she fled leaving her buckets of grapes among the vines, afraid that if the thieves did not steal them, the guards chasing them would trample them. Defias thugs still loiter among the rows. Nearby, in a shack across the bridge, the cutthroat Garrick Padfoot gathered a gang of thugs around him and preyed on farmers and merchants for weeks, boasting that the land belonged to the Brotherhood now.', 'warcraft.wiki.gg/wiki/Elwynn_Forest (vineyards once the pride of Stormwind); quest 3904 description; quest 6 description; creature_text 103 (This land belongs to the Defias Brotherhood now); DB spawns: Defias Thug 38 x71 and Garrick Padfoot 103 at -9056,-461'),
(1205, 1, 12, 5, 0, 0, 'Goldshire', 'Goldshire is the largest town in Elwynn after the capital, a crossroads where the roads from Stormwind and Northshire meet those running on toward Westfall and Redridge. Gnolls from Redridge once attacked it and were driven off by the Stormwind Army, and in the First War it was among the last towns to fall to the Horde. Rebuilt after the Second War, it is now Marshal Dughan''s headquarters. At its heart stands the Lion''s Pride Inn, whose keeper Farley promises rest to the tired and cold. Travelers gather there: the Redridge trader Remy ''Two Times'', the apothecary William Pestle, and once Stalvan Mistmantle, who lodged there seeking work as a tutor after abandoning his post as headmaster in Moonbrook.', 'warcraft.wiki.gg/wiki/Goldshire (roads, Gnoll War, last towns to fall in the First War, rebuilt with Turalyon''s support); quest 2158 reward text (Farley''s motto); quest 107 description (William Pestle staying at the Lion''s Pride Inn); npc_text 50017 (Remy from Redridge); page_text 18 (Stalvan lodging at the Lion''s Pride Inn after abandoning his Moonbrook post); quest 54 (Dughan in Goldshire); warcraft.wiki.gg/wiki/Elwynn_Forest (largest settlement after the capital)'),
(1206, 1, 12, 6, 0, 0, 'Fargodeep Mine', 'Fargodeep Mine lies almost due south of Goldshire, between the Stonefield and Maclure homesteads. Marshal Dughan had hoped the kobold trouble was confined to Northshire, but his scouts found Fargodeep overrun as well, with kobold tunnelers and miners digging through its shafts and a brute called Narg the Taskmaster lurking among them. The kobolds carry gold dust and fat wax candles out of its depths, and a gold-toothed kobold was seen fleeing inside with a widow''s lost necklace. Nor are the kobolds the only ones taking from the mine. The Defias are collecting gold from Elwynn''s mines, though Stormwind''s own miners have not worked them for months.', 'quest 62 description and reward text; quests 47, 60 (gold dust, large candles); quest 87 description (Goldtooth); page_text 79 (Defias gold collection from the Elwynn mines); quest 123 request text (no miners for months); DB spawns: Narg the Taskmaster 79 at -9733,115, Goldtooth 327 at -9746,88, Kobold Tunneler 475'),
(1207, 1, 12, 7, 0, 0, 'The Stonefield Farm', 'The Stonefield Farm lies west of Fargodeep Mine in southern Elwynn, home to a large and quarrelsome family. Ma Stonefield guards her vegetables from the Brackwells'' enormous prize sow, the widowed Auntie Bernice bakes pork belly pies and keeps a lucky trinket her husband forgot to take on his last campaign, Homer Stonefield sells fruit to passersby, and Gramma Stonefield keeps the house, trusted by her grandson to find a way where no one else can. The family is locked in a bitter feud with the Maclures to the east, which is hard on young Tommy Joe, who lingers by the river west of the farm, pining for Maybell Maclure.', 'quest 88 description; quests 85, 86, 87 (Bernice, widow, husband''s last campaign); creature_template 894 Homer Stonefield <Fruit Seller>; quests 106, 111 (feud, Tommy Joe at the river, Gramma); quest 62 (mine between the Stonefield and Maclure homesteads); warcraft.wiki.gg/wiki/Stonefield_Farm (rival farmsteads)'),
(1208, 1, 12, 8, 0, 0, 'The Maclure Vineyards', 'East of the Stonefields, beyond Fargodeep Mine, stand the Maclure Vineyards, where Joshua Maclure works as the family''s vintner. The Maclures keep up their long feud with the Stonefields, but not every Maclure shares the grudge. Young Maybell Maclure has given her heart to Tommy Joe Stonefield and calls herself cursed, since she cannot see him without crossing her own kin. Then there is young Billy Maclure, a hungry and slippery boy whom old Auntie Bernice accuses of taking her necklace, and who cannot seem to remember anything useful until someone brings him a pie.', 'quest 106 description; quests 85, 86, 87; creature_template 258 Joshua Maclure <Vintner>; quest 106 (Stonefield Farm due west of the Maclures); warcraft.wiki.gg/wiki/Stonefield_Farm (rival families)'),
(1209, 1, 12, 9, 0, 0, 'Jerod''s Landing', 'Jerod''s Landing is a boat landing on the Elwynn bank of the Nazferiti River, south of Goldshire where the forest meets the Duskwood border. It no longer serves honest trade. The Defias Brotherhood has seized it, and a Defias dockmaster now directs a crew of dockworkers on the riverbank, who carries the Brotherhood''s shipping schedule. Through the landing the thieves move stolen goods out of reach of the marshals, carried down from Redridge and bound for their holdings in Westfall.', 'warcraft.wiki.gg/wiki/Jerod''s_Landing (boat landing on the Nazferiti, Defias Dockmaster, smuggling stolen goods from Redridge to Klaven''s Tower in Westfall); DB spawns: Defias Dockmaster 6846 at -9959,-132 (about map 48,87) and Defias Dockworker 6927 x3; creature_loot_template: Defias Dockmaster drops Defias Shipping Schedule 7675'),
(1210, 1, 12, 10, 0, 0, 'Westbrook Garrison', 'Westbrook Garrison guards Elwynn''s western border, a barracks and guard tower just past the bridge over a small brook on the road to Westfall. Deputy Rainer, who holds it, has far too few men. He cannot believe the officials in Stormwind sent the bulk of the army abroad while thieves slip over from Westfall and gnolls press in from east and west. His pleas to Goldshire for soldiers bring only volunteers. The garrison''s quartermasters arm whoever will fight, a morale officer keeps spirits up, and a wanted poster outside calls for the death of the gnoll Hogger.', 'quest 239 description; npc_text 2286 (Deputy Rainer); quest 11 description (guard tower); creature_template 1645, 1249 quartermasters, 955 Sergeant De Vries <Morale Officer>; gameobject 68 Wanted Poster beside Rainer, starts quest 176; warcraft.wiki.gg/wiki/Westbrook_Garrison'),
(1211, 1, 12, 11, 0, 0, 'Forest''s Edge', 'Forest''s Edge is the wild southwestern corner of Elwynn, where the woods run down to the Westfall border. Packs of Riverpaw gnolls have made camps here, south of the Westbrook guard tower, in greater numbers than the garrison can handle alone, and the Stormwind Army rewards those who bring back their painted armbands. The gnolls do not act alone: some carry Defias schedules for the gold taken from Elwynn''s mines. The fierce Gruff Swiftbite roams among them, and above them all looms Hogger, a huge gnoll who has overpowered every attempt at his capture.', 'warcraft.wiki.gg/wiki/Elwynn_Forest (gnoll camps at Forest''s Edge); quest 11 description; quest 176 description; creature_loot_template: Gold Pickup Schedule 1307 drops from Riverpaw Runt, Riverpaw Outrunner, Gruff Swiftbite, Hogger; DB: Hogger 448 spawn has areaId 60; Gruff Swiftbite 100 spawns near -9988,609'),
(1212, 1, 12, 12, 0, 0, 'Crystal Lake', 'Crystal Lake lies just east of Goldshire, a bright stretch of water in the heart of the forest and an easy walk from the Lion''s Pride Inn. It is no longer a peaceful spot. Murlocs crowd its shores, and their streamrunners prowl the banks, making the lake dangerous for anyone careless enough to wander close. Some of the creatures carry crystal kelp, a frond that usually grows in the ocean, and the apothecary William Pestle prizes it for brewing an invisibility liquor.', 'quest 112 description; warcraft.wiki.gg/wiki/Crystal_Lake (directly east of Goldshire, crawling with murlocs); DB spawns: Murloc 285 x35 and Murloc Streamrunner 735 x21 around -9480,-350'),
(1213, 1, 12, 13, 0, 0, 'Tower of Azora', 'Along the road running east from Goldshire rises the Tower of Azora, where the high mage Theocritus presides. Servants of Azora tend its halls, a clothier and a dealer in arcane goods trade within, and its shelves hold histories of distant lands. Within the tower rests the Eye of Azora, a device Theocritus developed to gaze upon the Tower of Ilgalar in Redridge, lair of his bitter rival, the warlock Morganth. The two towers are locked in a constant feud, each spying on the other by magical means.', 'warcraft.wiki.gg/wiki/Tower_of_Azora (road from Goldshire to Eastvale, Eye of Azora, constant feud, mutual spying); quest 94 description; quest 178 description (High Mage of Tower Azora); DB spawns: Servant of Azora 1949 x10, Morley Eberlein <Clothier>, Dawn Brightstar <Arcane Goods>; gameobject 175760 Rise of the Blood Elves in the tower; quest 76 description (east along the road to the tower); DB: Eye of Azora gameobject 19548 inside the tower'),
(1214, 1, 12, 14, 0, 0, 'Jasperlode Mine', 'Jasperlode Mine lies in the foothills north of the Tower of Azora, the more distant of the two Elwynn mines that Marshal Dughan sent scouts to examine. The news was bad: kobolds had overrun it as well, and their geomancers and miners, with the trapper Ruklar, hold its approaches. Deeper inside, the kobolds share the dark tunnels with mine spiders, among them a great spider known as Mother Fang. Dughan received the report with a curse, declaring that the situation grew worse by the minute.', 'quest 76 description and reward text; quest 47 description (kobolds around the Jasperlode Mine); DB spawns: Kobold Geomancer 476 x8, Kobold Miner 40, Ruklar the Trapper 60 at -9251,-708, Mother Fang 471 at -9052,-621, Mine Spider 43 x8 around -9038,-587'),
(1215, 1, 12, 15, 0, 0, 'Stone Cairn Lake', 'Stone Cairn Lake spreads across northeastern Elwynn, ringed around a single large island. Murlocs have built a village on its shores, and they are aggressive and cunning enough to kill. Two soldiers from the eastern bridge, Rolf Hartford and Malakai Stone, went north along the river to investigate and never returned. Malakai''s half-eaten body was found by the water, and webbed footprints led along the shore to Rolf''s remains in the murloc village. The lake was once a safe place for pilgrims, but the island at its center is now held by Defias rogue wizards.', 'warcraft.wiki.gg/wiki/Stone_Cairn_Lake (ring shape around an island, murloc tribe, rogue wizards, formerly a safe pilgrimage site); quests 35, 37, 45, 46 (descriptions and reward texts); gameobject 55 A half-eaten body, 56 Rolf''s corpse; DB spawns: Murloc Lurker 732 and Murloc Forager 46 near Rolf''s corpse; Defias Rogue Wizard 474 x18 on the island'),
(1216, 1, 12, 16, 0, 0, 'Heroes'' Vigil', 'At the center of the island in Stone Cairn Lake stands Heroes'' Vigil, a ring of stones around the Stone of Remembrance. The monument honors all who fell defending Stormwind, above all in the First War, when the orcs sacked Goldshire and the lands around it. The Defias Brotherhood has found a use for a place the kingdom has nearly forgotten. Their orders name it a staging camp for reinforcements from Westfall, and Defias rogue wizards now hold it. Two paladins who came seeking proof of the plot were overwhelmed by their spells, and one fell holding them back so the other could escape.', 'warcraft.wiki.gg/wiki/Heroes''_Vigil (ring of stones, Stone of Remembrance, Rogue Wizards); npc_text 6062 (Stone of Remembrance inscription); page_text 811 (Defias Script: base camp, reinforcements from Westfall, all but forgotten); quests 1786, 1787 (Gazin and Henze Faulk); DB: gameobject 20923 at -9135,-1050; Henze Faulk 6172 at -9130,-984; Defias Rogue Wizard x18 on the island'),
(1217, 1, 12, 17, 0, 0, 'Brackwell Pumpkin Patch', 'The Brackwell Pumpkin Patch in southeastern Elwynn was the Brackwell family''s farm until bandits took it, and no one knows what became of the family. Their prize sow Princess remains, grown huge on vegetables stolen from the Stonefields, and trots about with a small entourage of pigs. The farm is now a Defias hideout. Gold taken from Elwynn''s mines is gathered here for a Brotherhood agent known only as the Collector, and here the young warlock Surena Caledon fled with the Defias bandit Erlan Drudgemoor, wearing a bloodstone choker her old master wants back.', 'warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch (pre-Cataclysm: Brackwells'' fate unknown, Defias control, Princess, Surena); quest 88 description; page_text 79 (Collector schedule); quest 147 description; quest 1688 description; DB spawns: Princess 330 and Porcine Entourage 390 x2, Morgan the Collector 473, Surena Caledon 881, Erlan Drudgemoor 880 around -9806,-930'),
(1218, 1, 12, 18, 0, 0, 'Eastvale Logging Camp', 'In eastern Elwynn, near the Redridge border, the Eastvale Logging Camp supplies the kingdom with lumber. Orders come steadily and deadlines are strict, so Supervisor Raelen frets when wolves and bears from the woods to the north chase her workers away from their chopped bundles. Sara Timberlain fashions armor for the forest''s defenders, and at the stables Katie and Randal Hunter breed horses and teach riding, though only to those who have earned Stormwind''s full trust. Just southeast of the camp stands the manor of the retired Marshal Haggard, once a noble family''s summer cottage.', 'warcraft.wiki.gg/wiki/Eastvale_Logging_Camp (lumber orders, deadlines, stables, Haggard''s manor); quest 5545 description; quest 52 description; quests 59, 83 (Sara Timberlain); npc_text 4859, 5855, 5861 (Katie and Randal Hunter); warcraft.wiki.gg/wiki/Marshal_Haggard (manor southeast of Eastvale, former Flintridge summer cottage); page_text 20 (the Lord''s summer cottage near Eastvale)'),
(1219, 2, 12, 1, 1, 0, 'Marshal Dughan', 'Marshal Dughan commands the Stormwind Army''s forces in Goldshire and answers for the safety of the town and the forest around it. It is a thankless post. With the army fighting far away, he must make do with deputies and volunteers while kobolds fill the mines, gnolls and thieves press from the west, and new troubles arrive faster than he can answer them. He is a cautious man, unwilling to send scarce troops east on a merchant''s word, but he heeds his soldiers: when Guard Thomas reported two of his men dead, Dughan took the murloc threat seriously at last. He has posted a generous bounty on the gnoll Hogger.', 'npc_text 16211 (Dughan gossip); quest 54 reward text (army busy abroad); quest 40 reward text; quest 39 reward text; quests 62, 76, 123, 147, 176, 239; warcraft.wiki.gg/wiki/Marshal_Dughan (pre-Cataclysm section)'),
(1220, 2, 12, 2, 1, 0, 'Marshal McBride', 'Marshal Douglas McBride commands the Stormwind Army garrison at Northshire Abbey and the defense of the valley. With so many soldiers sent abroad, he depends on volunteers, and he sends each newcomer first against the kobolds in the northern woods and the Echo Ridge Mine. His careful written reports track the kobolds, the wolves driven out of Duskwood and the red-bandanaed thieves who have appeared in the valley, and they name one of the gang''s leaders, Garrick Padfoot. Those who serve Northshire well leave with his signed commendation, granting them deputy status and sending them on to Goldshire.', 'npc_text 4938 (McBride gossip); quest 783 reward text (forces marshaled abroad); quests 7, 15, 21, 54; page_text 209-212 (McBride''s reports and commendation, signed Marshal Douglas McBride); warcraft.wiki.gg/wiki/Marshal_McBride'),
(1221, 2, 12, 3, 0, 0, 'Hogger', 'Hogger is a huge gnoll who prowls the woods of southwestern Elwynn as chieftain of the Riverpaw pack. Since the Third War the Riverpaw have raided farms and villages across the forest, armed and guided, it is said, by the Defias Brotherhood. Hogger himself has overpowered every attempt to capture him, and the Stormwind Army now offers a generous bounty for proof of his death, paid by Marshal Dughan in Goldshire. Dughan admits the beast has given him a headache the size of Blackrock Spire.', 'warcraft.wiki.gg/wiki/Hogger (pre-Cataclysm: Riverpaw chieftain, raids after the Third War, Defias weapons and leadership); quest 176 description and reward text; creature_text 448'),
(1222, 2, 12, 4, 0, 0, 'Morgan the Collector', 'Morgan, known in Defias papers only as the Collector, is the Brotherhood''s agent in Elwynn Forest, hiding out at the Brackwell Pumpkin Patch. Twice a week, by a schedule that turns up among the Riverpaw gnolls, gold dug from the forest''s mines is gathered at the farm for him, bound for the Brotherhood''s headquarters in Westfall. He is known by an engraved ring given to him by his master. That ring proved to be a membership band of the old Stonemasons'' Guild of Stormwind, an odd possession for a common thief, and a clue that ties the Brotherhood to that guild.', 'page_text 79 (Collector''s schedule: Sunday and Wednesday, headquarters in Westfall, engraved ring); quest 123 description; quest 147 description and reward text; creature_loot_template: Gold Pickup Schedule drops from Riverpaw gnolls; warcraft.wiki.gg/wiki/Morgan_the_Collector (Defias, former Stonemason, Brackwell Pumpkin Patch)'),
(1223, 2, 12, 5, 1, 0, 'Theocritus', 'Theocritus is the high mage of the Tower of Azora, a scholar who would rather fight his battles from afar. Through the Eye of Azora, a device of his own making, he spies on his rival Morganth, a vicious warlock of great power who rules the Tower of Ilgalar in Redridge. He has learned that Morganth seeks the Scythe of Elune and may already have found it, a peril to Redridge and to Stormwind itself. Theocritus also studies the pendants by which Morganth speaks to the Shadowhide gnolls, hoping one day to strike through them, though he admits much more research is needed.', 'quest 94 description and reward text; quest 249 description (I am not prepared to pit myself against Morganth); quest 178 description and reward text; creature_template 313 <Mage of Tower Azora>; warcraft.wiki.gg/wiki/Tower_of_Azora'),
(1224, 2, 12, 6, 1, 0, 'Marshal Haggard', 'Marshal Haggard once led men of the Stormwind Guard and now lives in retirement in a manor just southeast of the Eastvale Logging Camp, among the weapons of a long career. His eyes are failing. On a dark night the Defias rogue Dead-tooth Jack came to him wearing a Stormwind tabard, and Haggard, taking him for Marshal Dughan, handed over his old marshal''s badge before the thief laughed and ran off to his camp somewhere to the south. The manor holds older secrets too: a chest upstairs, there when Haggard moved in, held pages from the journal of Stalvan Mistmantle.', 'quest 1666 description (retired, collected a lot of gear); quest 1667 description and reward text; quest 75 description; warcraft.wiki.gg/wiki/Marshal_Haggard (former leader of the Stormwind Guard, manor southeast of Eastvale, eyesight); DB: Dead-Tooth Jack 6093 at -9769,-1566 (south of the manor)'),
(1225, 2, 12, 7, 1, 0, 'Guard Thomas', 'Guard Thomas was posted to Elwynn''s eastern bridge for the Stormwind Army, keeping watch over the road toward the Eastvale Logging Camp. From there he sees the forest''s troubles firsthand: wolves and bears grown bold, and murlocs settling into the eastern streams. When he sent two guards, Rolf Hartford and Malakai Stone, north along the river to investigate, neither came back. Learning that both had died at the murlocs'' hands, he warned Goldshire that his small force could not contain the creatures, and he pays the army''s bounty on their fins.', 'quests 35, 37, 39, 46, 52, 71 (descriptions and reward texts); quest 59 description (Eastvale beyond Guard Thomas'' post); npc_text 50018'),
(1226, 2, 12, 8, 1, 0, 'Remy ''Two Times''', 'Remy, known as ''Two Times'' for his habit of saying everything twice, is a trader from Redridge who came to Goldshire looking for business. He buys the gold dust that kobolds carry out of the mines, promising the best price in town, and pays in coin along with tokens from certain associates of his. Remy was also the first to raise the alarm about murlocs swimming up the eastern streams, scaring off fish and attacking gentle folk, though Marshal Dughan, respecting him as a merchant, dismissed the warning until his own soldiers confirmed it.', 'npc_text 50017 (from Redridge, looking for business, repeats himself); quest 47 description and reward text; quest 40 description and reward text; quest 39; warcraft.wiki.gg/wiki/Remy_%22Two_Times%22 (nickname from repeating the ends of his sentences, merchant from Redridge)'),
(1227, 3, 12, 1, 1, 0, 'The Defense of Northshire', 'Northshire''s guards are stretched thin, so Deputy Willem stands outside the abbey enlisting anyone willing to defend their home. Marshal McBride sends each volunteer first to cull the kobold vermin in the northern woods, then to the Echo Ridge Mine, where the infestation proves larger than feared. Meanwhile the hunter Eagan Peltskinner asks for the diseased young wolves to be put down before their sickness spreads, and the deputy offers rewards for the red bandanas of a new gang calling itself the Defias Brotherhood, one of whose leaders, Garrick Padfoot, hides with his thugs near the vineyards. Milly Osworth needs her abandoned grapes rescued from those same thieves, to the joy of Brother Neals, who keeps the abbey''s food and drink. When the valley is safer, McBride signs commendations naming his best volunteers deputies and sends them south to Marshal Dughan in Goldshire.', 'quests 783, 7, 15, 21, 33, 5261, 18, 6, 3903, 3904, 3905, 54 (descriptions and reward texts); page_text 209-212'),
(1228, 3, 12, 2, 1, 0, 'Kobolds in the Mines', 'Kobolds have spread from Northshire across Elwynn. Marshal Dughan, already troubled by gnolls and thieves, sends scouts first to the Fargodeep Mine south of Goldshire and then to the more distant Jasperlode Mine in the eastern foothills. Both prove infested, and Dughan curses that the situation worsens by the minute. Not everyone in Goldshire sees only trouble. The apothecary William Pestle wants the large wax candles the kobolds wear on their heads, to ship to his brother Morgan''s shop in Stormwind, and Remy ''Two Times'' pays well for the gold dust they carry. That gold hints at a deeper theft. The Defias Brotherhood is collecting gold from these same mines and sending it to Westfall, though Stormwind''s own miners have not worked them for months.', 'quests 62, 76, 60, 61, 47 (descriptions and reward texts); page_text 15 (William''s shipment note); page_text 79; quest 123 request text'),
(1229, 3, 12, 3, 1, 0, 'The Collector', 'The trail begins with a scrap of paper. Some of the Riverpaw gnolls carry a schedule describing how gold from the Elwynn mines is gathered twice a week at the Brackwell Pumpkin Patch, to be handed to an agent known only as the Collector and recognized by an engraved ring. Marshal Dughan is astonished, for the kingdom has had no miners in those tunnels for months. Whoever is taking that gold is stealing from the crown, he reasons, and he orders the Collector brought to justice. The ring taken from the thief raises more questions than it answers. It is a membership ring of the old Stonemasons'' Guild of Stormwind, and Dughan cannot say why a common bandit would wear a craftsman''s guild ring, or why the Defias would be gathering money from the kingdom''s mines. He can only hope the answers will come.', 'page_text 79; quest 123 description, request and reward text; quest 147 description and reward text; creature_loot_template: item 1307 Gold Pickup Schedule from Riverpaw Runt, Outrunner, Gruff Swiftbite, Hogger'),
(1230, 3, 12, 4, 1, 0, 'Murlocs in the East', 'Remy ''Two Times'' was the first to warn of murlocs swimming up the streams of eastern Elwynn, but Marshal Dughan, busy with gnolls and bandits, would act only on a military report. That report came from Guard Thomas at the eastern bridge. The murlocs had settled into the streams, aggressive and cleverer than anyone expected, and two of his guards, Rolf Hartford and Malakai Stone, had gone north along the river and never returned. Malakai''s half-eaten body lay by the water, and webbed footprints led to Rolf''s remains in a murloc village on the shore of Stone Cairn Lake, each identified by the medallion bearing his name. Their deaths troubled Dughan, who feared fighting in Goldshire by week''s end, and at the bridge Thomas pays the Stormwind Army''s bounty on murloc fins.', 'quests 40, 35, 37, 45, 71, 39, 46 (descriptions and reward texts); gameobjects 55, 56'),
(1231, 3, 12, 5, 1, 0, 'The Stonefields and the Maclures', 'Two farming families of southern Elwynn, the Stonefields and the Maclures, have long been bitter enemies, and their children pay the price. Maybell Maclure loves Tommy Joe Stonefield and sends him a secret letter. Tommy Joe turns to his Gramma, who sees no end to the feud but wants the pair to have a little time together, and she asks the apothecary William Pestle in Goldshire for help. With crystal kelp taken from the murlocs of Crystal Lake, he brews an invisibility liquor so Maybell can slip away to her love unseen. Not every tale between the farms is so tender. Auntie Bernice Stonefield blames young Billy Maclure for her missing necklace, and Billy, bribed with one of her own pies, swears after a slip of the tongue that he only saw a gold-toothed kobold carry it into Fargodeep Mine. Ma Stonefield, meanwhile, wants the Brackwells'' greedy sow Princess dead before she eats another crop.', 'quests 106, 111, 107, 112, 114 (descriptions and reward texts); quests 85, 86, 84, 87 (descriptions and reward texts); quest 88 description and reward text; warcraft.wiki.gg/wiki/Stonefield_Farm'),
(1232, 3, 12, 6, 1, 0, 'The Western Border', 'With the bulk of Stormwind''s army sent abroad, Westbrook Garrison on Elwynn''s western border is struggling. Word reaches Goldshire of growing gnoll and thief activity, but Marshal Dughan has no soldiers to spare and can send only volunteers to Deputy Rainer. Riverpaw gnolls have settled in the woods south of the garrison''s tower, in numbers greater than the guards can handle, and the army rewards anyone who brings back their painted armbands. The gnolls are more than a nuisance: some carry the Defias schedule for the gold stolen from Elwynn''s mines, a sign that the pack and the Brotherhood work hand in hand. Looming over them all is Hogger, a gnoll so huge that he has overpowered every attempt at capture, and whose claw is worth a generous bounty in Goldshire.', 'quests 239, 11, 176 (descriptions and reward texts); npc_text 2286; creature_loot_template: item 1307 from Riverpaw gnolls; warcraft.wiki.gg/wiki/Hogger (Defias supplied the Riverpaw)');
